EVENTINFO(autofish_event_info)
{
	DWORD pid;
	bool bGutFish;
	bool bDropJunk;
	bool bUseMinnow;
	bool bOpenClams;
	bool bAutoBuyBait;
	DWORD dwNextCastTime;

	autofish_event_info()
		: pid(0)
		, bGutFish(false)
		, bDropJunk(false)
		, bUseMinnow(false)
		, bOpenClams(false)
		, bAutoBuyBait(false)
		, dwNextCastTime(0)
	{}
};

struct FFindNearbyFisherman
{
	LPCHARACTER m_ch;
	bool m_bFound;
	FFindNearbyFisherman(LPCHARACTER ch) : m_ch(ch), m_bFound(false) {}
	void operator () (LPENTITY ent)
	{
		if (m_bFound || !ent || !ent->IsType(ENTITY_CHARACTER))
			return;
		LPCHARACTER npc = (LPCHARACTER) ent;
		if (npc->GetRaceNum() == 9009)
		{
			if (DISTANCE_APPROX(npc->GetX() - m_ch->GetX(), npc->GetY() - m_ch->GetY()) <= 8000)
				m_bFound = true;
		}
	}
};

EVENTFUNC(autofish_event)
{
	autofish_event_info* info = dynamic_cast<autofish_event_info*>(event->info);
	if (!info)
		return 0;

	LPCHARACTER ch = CHARACTER_MANAGER::instance().FindByPID(info->pid);
	if (!ch)
		return 0;

	if (ch->IsDead())
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: postać zginęła.");
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}

	if (ch->IsStateMove())
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: ruch postaci.");
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}

	// 1. Minigra w toku (m_pkFishingEvent)
	if (ch->m_pkFishingEvent && ch->IsPlayingFishGame())
	{
		using fishing::fishing_event_info;
		struct fishing_event_info* gameInfo = dynamic_cast<struct fishing_event_info*>(ch->m_pkFishingEvent->info);
		if (gameInfo && ch->m_biFishGameState >= 2) // FISHING_GAME_STATE_IN_PROGRESS
		{
			const int top = (int)gameInfo->bar_position + (int)gameInfo->bar_height;
			for (int presses = 0; presses < 16 && ch->m_iFish_position + 8 <= top + 1; ++presses)
			{
				fishing::Take(gameInfo, ch);
			}
			if ((int)gameInfo->bar_position + (int)gameInfo->bar_height >= 100)
			{
				ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishNotify fish");
			}
		}
		info->dwNextCastTime = get_dword_time() + 2500;
		return (passes_per_sec / 4);
	}

	// 2. Faza brania (m_pkPreFishingEvent)
	if (ch->m_pkPreFishingEvent)
	{
		if (ch->m_bPlayerFishReactTime > 0)
		{
			DWORD now = get_dword_time();
			DWORD delta = now - ch->m_bPlayerFishReactTime;
			if (delta >= 1900 && delta <= 3300)
			{
				ch->fishing_take();
				ch->m_bPlayerFishReactTime = 0;
			}
		}
		info->dwNextCastTime = get_dword_time() + 2500;
		return (passes_per_sec / 4);
	}

	// 3. Po zakończeniu poprzedniego rzutu: odczekaj bufor czasowy
	DWORD now = get_dword_time();
	if (now < info->dwNextCastTime)
	{
		return (passes_per_sec / 2);
	}

	// 4. Sprzątanie po wyłowieniu (patroszenie ryb / wyrzucanie farb / otwieranie małży)
	if (info->bDropJunk)
	{
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (!it) continue;
			DWORD v = it->GetVnum();
			// Farby do włosów: 70201 - 70206, Wybielacz: 70207
			if (v >= 70201 && v <= 70207)
			{
				ITEM_MANAGER::instance().RemoveItem(it, "AUTOFISH_JUNK");
			}
		}
	}

	if (info->bGutFish)
	{
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (!it) continue;
			if (it->GetType() == ITEM_FISH && it->GetSubType() == FISH_ALIVE)
			{
				ch->UseItem(TItemPos(INVENTORY, cell));
			}
		}
	}

	if (info->bOpenClams)
	{
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (!it) continue;
			if (it->GetVnum() == 27987) // Małż
			{
				ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishNotify clam");
				ch->UseItem(TItemPos(INVENTORY, cell));
			}
		}
	}

	// 5. Sprawdzenie wolnego miejsca
	if (ch->GetEmptyInventory(1) < 0)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: brak miejsca w ekwipunku!");
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}

	// 6. Sprawdzenie wędki
	LPITEM rod = ch->GetWear(WEAR_WEAPON);
	if (!rod || rod->GetType() != ITEM_ROD)
	{
		LPITEM bagRod = NULL;
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetType() == ITEM_ROD)
			{
				bagRod = it;
				break;
			}
		}
		if (bagRod)
		{
			ch->EquipItem(bagRod);
			rod = ch->GetWear(WEAR_WEAPON);
		}
	}
	if (!rod || rod->GetType() != ITEM_ROD)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: brak wędki w ręku lub ekwipunku!");
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}

	// 7. Sprawdzenie i założenie przynęty
	bool bNeedBait = (rod->GetSocket(2) == 0);
	if (!bNeedBait && info->bUseMinnow && rod->GetSocket(2) != 27802)
	{
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetVnum() == 27802)
			{
				bNeedBait = true;
				break;
			}
		}
	}

	if (bNeedBait)
	{
		LPITEM bait = NULL;
		static const DWORD s_baitNormal[] = { 27801, 27800 };
		static const DWORD s_baitMinnowFirst[] = { 27802, 27801, 27800 };
		const DWORD* pBaitList = info->bUseMinnow ? s_baitMinnowFirst : s_baitNormal;
		const size_t baitCount = info->bUseMinnow ? 3 : 2;

		for (size_t b = 0; b < baitCount; ++b)
		{
			for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
			{
				LPITEM it = ch->GetInventoryItem(cell);
				if (it && it->GetVnum() == pBaitList[b])
				{
					bait = it;
					break;
				}
			}
			if (bait) break;
		}

		if (!bait && info->bAutoBuyBait)
		{
			if (ch->GetSectree())
			{
				FFindNearbyFisherman f(ch);
				ch->GetSectree()->ForEachAround(f);
				if (!f.m_bFound)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Nie znaleziono Rybaka w pobliżu (do 80m)!");
				}
				else if (ch->GetGold() < 2000)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Brak Yang na zakup robaków (wymagane 2.000 Yang)!");
				}
				else if (ch->GetEmptyInventory(1) < 0)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Brak miejsca w ekwipunku na zakup robaków!");
				}
				else
				{
					ch->PointChange(POINT_GOLD, -2000, true);
					ch->AutoGiveItem(27801, 50);
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Dokupiono 50 szt. Robaków u Rybaka za 2.000 Yang.");
					for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
					{
						LPITEM it = ch->GetInventoryItem(cell);
						if (it && it->GetVnum() == 27801)
						{
							bait = it;
							break;
						}
					}
				}
			}
		}

		if (!bait)
		{
			ch->ChatPacket(CHAT_TYPE_INFO, info->bUseMinnow ? "Auto-Wędkowanie przerwane: skończyła się przynęta (drobne ryby/robaki/papka)!" : "Auto-Wędkowanie przerwane: skończyła się przynęta (robaki/papka)!");
			ch->m_pkAutoFishEvent = NULL;
			ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
			return 0;
		}

		rod->SetSocket(2, bait->GetVnum(), true, "SOCKET_FISHING");
		if (bait->GetCount() > 1)
			bait->SetCount(bait->GetCount() - 1);
		else
			ITEM_MANAGER::instance().RemoveItem(bait, "AUTOFISH_BAIT");
	}

	// 8. Sprawdzenie Karnetu Rybackiego (UNIQUE_ITEM_FISHING_PASS = 27620)
	if (!ch->IsEquipUniqueItem(UNIQUE_ITEM_FISHING_PASS))
	{
		LPITEM passItem = NULL;
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetVnum() == UNIQUE_ITEM_FISHING_PASS)
			{
				passItem = it;
				break;
			}
		}
		if (passItem)
			ch->EquipItem(passItem);

		if (!ch->IsEquipUniqueItem(UNIQUE_ITEM_FISHING_PASS))
		{
			ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: brak założonego Karnetu Rybackiego!");
			ch->m_pkAutoFishEvent = NULL;
			ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
			return 0;
		}
	}

	// 9. Sprawdzenie wody
	LPSECTREE_MAP pkSectreeMap = SECTREE_MANAGER::instance().GetMap(ch->GetMapIndex());
	if (!pkSectreeMap)
	{
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}
	LPSECTREE tree = pkSectreeMap->Find(ch->GetX(), ch->GetY());
	if (!tree || tree->IsAttr(ch->GetX(), ch->GetY(), ATTR_BLOCK) || !tree->IsNearAttr(ch->GetX(), ch->GetY(), ATTR_WATER))
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie przerwane: brak wody w pobliżu!");
		ch->m_pkAutoFishEvent = NULL;
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return 0;
	}

	// 10. Start rzutu!
	ch->fishing();
	info->dwNextCastTime = get_dword_time() + 2500;
	return (passes_per_sec / 2);
}

ACMD(do_autofish)
{
	char arg1[256], arg2[256], arg3[256], arg4[256], arg5[256], arg6[256];
	const char* rest = two_arguments(argument, arg1, sizeof(arg1), arg2, sizeof(arg2));
	rest = two_arguments(rest, arg3, sizeof(arg3), arg4, sizeof(arg4));
	two_arguments(rest, arg5, sizeof(arg5), arg6, sizeof(arg6));

	if (!*arg1 || !strcmp(arg1, "0") || !strcmp(arg1, "off") || !strcmp(arg1, "stop"))
	{
		if (ch->m_pkAutoFishEvent)
		{
			event_cancel(&ch->m_pkAutoFishEvent);
			ch->ChatPacket(CHAT_TYPE_INFO, "Automatyczne wędkowanie zostało zatrzymane.");
		}
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	if (ch->m_pkAutoFishEvent)
	{
		event_cancel(&ch->m_pkAutoFishEvent);
	}

	if (ch->IsDead())
		return;

	if (ch->GetLevel() < 30)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Wędkowanie jest dostępne od 30 poziomu.");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	if (!CanFishOnMapIndex(ch->GetMapIndex()))
	{
		ch->ChatPacket(CHAT_TYPE_INFO, LC_TEXT("FISHING_MAP_INDEX"));
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	if (ch->GetQuestFlag("fishing_onboarding.completed") < 1)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, LC_TEXT("FISHING_NEED_ONBOARDING"));
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	if (ch->IsRiding())
	{
		ch->StopRiding();
		ch->HorseSummon(false);
	}

	LPSECTREE_MAP pkSectreeMap = SECTREE_MANAGER::instance().GetMap(ch->GetMapIndex());
	if (!pkSectreeMap)
		return;
	LPSECTREE tree = pkSectreeMap->Find(ch->GetX(), ch->GetY());
	if (!tree || tree->IsAttr(ch->GetX(), ch->GetY(), ATTR_BLOCK) || !tree->IsNearAttr(ch->GetX(), ch->GetY(), ATTR_WATER))
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Podejdź do brzegu rzeki lub morza, aby łowić ryby!");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	// Sprawdzenie wędki
	LPITEM rod = ch->GetWear(WEAR_WEAPON);
	if (!rod || rod->GetType() != ITEM_ROD)
	{
		LPITEM bagRod = NULL;
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetType() == ITEM_ROD)
			{
				bagRod = it;
				break;
			}
		}
		if (bagRod)
		{
			ch->EquipItem(bagRod);
			rod = ch->GetWear(WEAR_WEAPON);
		}
	}
	if (!rod || rod->GetType() != ITEM_ROD)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Musisz posiadać wędkę w ręku lub w ekwipunku!");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	// Sprawdzenie Karnetu Rybackiego
	if (!ch->IsEquipUniqueItem(UNIQUE_ITEM_FISHING_PASS))
	{
		LPITEM passItem = NULL;
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetVnum() == UNIQUE_ITEM_FISHING_PASS)
			{
				passItem = it;
				break;
			}
		}
		if (passItem)
			ch->EquipItem(passItem);
	}
	if (!ch->IsEquipUniqueItem(UNIQUE_ITEM_FISHING_PASS))
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Wymagany jest założony Karnet Rybacki (kupisz go u Rybaka).");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	bool bGut = (*arg2 == '1');
	bool bDropJunk = (*arg3 == '1');
	bool bUseMinnow = (*arg4 == '1');
	bool bOpenClams = (*arg5 == '1');
	bool bAutoBuyBait = (*arg6 == '1');

	// Sprawdzenie przynęty
	bool bNeedBait = (rod->GetSocket(2) == 0);
	if (!bNeedBait && bUseMinnow && rod->GetSocket(2) != 27802)
	{
		for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
		{
			LPITEM it = ch->GetInventoryItem(cell);
			if (it && it->GetVnum() == 27802)
			{
				bNeedBait = true;
				break;
			}
		}
	}

	if (bNeedBait)
	{
		LPITEM bait = NULL;
		static const DWORD s_baitNormal[] = { 27801, 27800 };
		static const DWORD s_baitMinnowFirst[] = { 27802, 27801, 27800 };
		const DWORD* pBaitList = bUseMinnow ? s_baitMinnowFirst : s_baitNormal;
		const size_t baitCount = bUseMinnow ? 3 : 2;

		for (size_t b = 0; b < baitCount; ++b)
		{
			for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
			{
				LPITEM it = ch->GetInventoryItem(cell);
				if (it && it->GetVnum() == pBaitList[b])
				{
					bait = it;
					break;
				}
			}
			if (bait) break;
		}

		if (!bait && bAutoBuyBait)
		{
			if (ch->GetSectree())
			{
				FFindNearbyFisherman f(ch);
				ch->GetSectree()->ForEachAround(f);
				if (!f.m_bFound)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Nie znaleziono Rybaka w pobliżu (do 80m)!");
				}
				else if (ch->GetGold() < 2000)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Brak Yang na zakup robaków (wymagane 2.000 Yang)!");
				}
				else if (ch->GetEmptyInventory(1) < 0)
				{
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Brak miejsca w ekwipunku na zakup robaków!");
				}
				else
				{
					ch->PointChange(POINT_GOLD, -2000, true);
					ch->AutoGiveItem(27801, 50);
					ch->ChatPacket(CHAT_TYPE_INFO, "Auto-Wędkowanie: Dokupiono 50 szt. Robaków u Rybaka za 2.000 Yang.");
					for (WORD cell = 0; cell < INVENTORY_AND_EQUIP_SLOT_MAX; ++cell)
					{
						LPITEM it = ch->GetInventoryItem(cell);
						if (it && it->GetVnum() == 27801)
						{
							bait = it;
							break;
						}
					}
				}
			}
		}

		if (!bait)
		{
			ch->ChatPacket(CHAT_TYPE_INFO, bUseMinnow ? "Brak przynęty (drobnych ryb/robaków/papki) w ekwipunku!" : "Brak przynęty (robaków/papki) w ekwipunku!");
			ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
			return;
		}

		rod->SetSocket(2, bait->GetVnum(), true, "SOCKET_FISHING");
		if (bait->GetCount() > 1)
			bait->SetCount(bait->GetCount() - 1);
		else
			ITEM_MANAGER::instance().RemoveItem(bait, "AUTOFISH_BAIT");
	}

	if (ch->GetEmptyInventory(1) < 0)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Ekwipunek jest pełny!");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 0 0 0 0 0 0");
		return;
	}

	autofish_event_info* info = AllocEventInfo<autofish_event_info>();
	info->pid = ch->GetPlayerID();
	info->bGutFish = bGut;
	info->bDropJunk = bDropJunk;
	info->bUseMinnow = bUseMinnow;
	info->bOpenClams = bOpenClams;
	info->bAutoBuyBait = bAutoBuyBait;
	info->dwNextCastTime = 0;
	ch->m_pkAutoFishEvent = event_create(autofish_event, info, PASSES_PER_SEC(0.25));

	ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoFishStatus 1 %d %d %d %d %d", bGut ? 1 : 0, bDropJunk ? 1 : 0, bUseMinnow ? 1 : 0, bOpenClams ? 1 : 0, bAutoBuyBait ? 1 : 0);
	ch->ChatPacket(CHAT_TYPE_INFO, "Automatyczne wędkowanie zostało włączone.");

	if (!ch->m_pkPreFishingEvent && !ch->m_pkFishingEvent)
	{
		ch->fishing();
	}
}

